// === Tab: mySketch ===
// Gumowski-Mira Attractor 
setup = _ => {
	createCanvas(windowWidth, windowHeight)
	colorMode(HSB, 255);
	w = max(width, height)
	x = y = 0
  sca1e=w/36
}

draw = _ => {
	background(w, 10)
	translate(width / 2, height / 2)
	x++
	for (i = 5e3; i--;) {
		tmp = y - .97 * x + 5 / (1 + x * x) - 5
		y = -.995 * x
		x = tmp
		di = dist(x,y,0,0);
		stroke(di*10%255, 255, 200);
		point(x * sca1e, y * sca1e)
	}
}

let lapse=0;mousePressed=()=>{if (millis()-lapse>400){save('pix.jpg');lapse =millis();}}

